use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        // If input is empty, output is empty
        (numbers.len() == 0 ==> res.len() == 0) &&
        // If input non-empty, output length is 2 * n - 1
        (numbers.len() > 0 ==> res.len() == 2 * numbers.len() - 1) &&
        // Even indices of output hold input elements
        (forall |i: usize| i < numbers.len() ==> res[2 * i] == numbers[i]) &&
        // Odd indices of output hold delimiter
        (forall |j: usize| j + 1 < res.len() && j % 2 == 0 ==> res[j + 1] == delim),
    decreases numbers.len(),
{
    let n = numbers.len();
    if n == 0 {
        // empty input, empty output
        return Vec::new();
    }

    let mut res = Vec::with_capacity(2 * n - 1);
    let mut i = 0;

    while i < n
        invariant
            i <= n,
            res.len() == 2 * i.saturating_sub(1), // for i=0, 2*0-1 saturating is 0
            // Elements at even indices: for all 0 <= k < i, res[2*k] == numbers[k]
            forall(|k: usize| (k < i) ==> res[2 * k] == numbers[k]),
            // Elements at odd indices: for all 0 <= k < i-1, res[2*k+1] == delim
            forall(|k: usize| (k + 1 < i) ==> res[2 * k + 1] == delim),
        decreases n - i,
    {
        // Push the input element
        res.push(numbers[i]);

        // If not the last element, push delimiter
        if i < n - 1 {
            res.push(delim);
        }

        i += 1;
    }

    res
}

} 

